def get_citeas_data(resource, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now_iso + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _norm_resource(x):
        x = x.strip()
        x = re.sub(r"\s+", " ", x)
        x = x.strip()
        doi = x.lower()
        doi = re.sub(r"^https?://(dx\.)?doi\.org/", "", doi).strip()
        doi = re.sub(r"^doi:\s*", "", doi).strip()
        if re.match(r"^10\.\d{4,9}/\S+$", doi):
            return "doi:" + doi
        return x

    def _cache_key(provider, resource_norm, results_requested):
        base = f"{provider}|{resource_norm}|{'' if results_requested is None else int(results_requested)}"
        ck = hashlib.sha256(base.encode("utf-8")).hexdigest()
        return f"ck_{ck}"

    def _extract_bibtex_key(bibtex):
        m = re.search(r"@\w+\s*\{\s*([^,\s]+)\s*,", bibtex or "", flags=re.IGNORECASE)
        return m.group(1) if m else None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, client_id, status, detail=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rl"),
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            return
        return

    # ---- validation
    if not isinstance(resource, str) or not resource.strip():
        _log("get_citeas_data", None, "error", "validation_error")
        return _err("VALIDATION_ERROR", "resource must be a non-empty string")

    # ---- ambient auth: pick an active client that can serve (exists and not deleted/suspended)
    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        _log("get_citeas_data", None, "error", "unauthorized")
        return _err("UNAUTHORIZED", "No active API client is permitted to use the service")

    client = active_clients[0]
    client_id = client.get("id")

    # ---- compute cache key + reuse/create request
    resource_norm = _norm_resource(resource)
    ck = _cache_key("citeas", resource_norm, None)
    if not (8 <= len(ck) <= 256):
        _log("get_citeas_data", client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "cache_key length invalid (internal)")

    reqs = _load("citation_requests.json")
    cits = _load("citations.json")
    attempts = _load("provider_attempts.json")
    pubs = _load("publications.json")

    # Find existing request (unique client_id, cache_key)
    existing_req = None
    for r in reqs:
        if isinstance(r, dict) and r.get("client_id") == client_id and r.get("cache_key") == ck:
            existing_req = r
            break

    # If succeeded and citations exist -> cache hit
    if existing_req and existing_req.get("status") == "succeeded":
        req_id = existing_req.get("id")
        matched = [x for x in cits if isinstance(x, dict) and x.get("request_id") == req_id and x.get("status") == "active"]
        matched.sort(key=lambda x: x.get("result_rank") or 0)
        if len(matched) >= 1:
            # update cache_hit=true (allowed terminal status change except updated_at; cache_hit is metadata; updated_at allowed)
            existing_req["cache_hit"] = True
            existing_req["updated_at"] = now_iso
            try:
                _save("citation_requests.json", reqs)
            except Exception:
                _log("get_citeas_data", client_id, "error", "storage_error")
                return _err("CONFLICT", "Failed to persist cache_hit update")
            _log("get_citeas_data", client_id, "ok", "cache_hit")
            return {
                "request": existing_req,
                "citations": matched[:1],
                "cached": True,
            }

    # If request exists but terminal without citations, do not mutate status; proceed via new attempt only if not terminal?
    # Business rules: once terminal, status must not change; and we can't create attempt if parent not queued/running.
    # Therefore, if existing request is terminal but unusable, create a NEW request by varying cache_key is not allowed.
    # Instead, treat as NOT_FOUND/failed replay? Real behavior: would reuse and return failure. We'll return NOT_FOUND.
    if existing_req and existing_req.get("status") in ("succeeded", "failed", "cancelled"):
        _log("get_citeas_data", client_id, "error", "not_found")
        return _err("NOT_FOUND", "No cached citation available for this resource")

    # Ensure or create request in queued state
    if existing_req is None:
        req_id = _new_id("cr")
        new_req = {
            "id": req_id,
            "client_id": client_id,
            "provider": "citeas",
            "resource": resource,
            "query": None,
            "results_requested": None,
            "status": "queued",
            "cache_key": ck,
            "cache_hit": False,
            "error_code": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(new_req)
        existing_req = new_req
        try:
            _save("citation_requests.json", reqs)
        except Exception:
            _log("get_citeas_data", client_id, "error", "storage_error")
            return _err("CONFLICT", "Failed to persist citation request")

    # ---- quota enforcement (counts successful attempts only; cached responses don't count)
    def _attempt_succeeded(a):
        return isinstance(a, dict) and a.get("status") == "succeeded" and a.get("request_id") in req_id_set

    # Precompute request ids for this client (for efficient counting)
    client_req_ids = set()
    for r in reqs:
        if isinstance(r, dict) and r.get("client_id") == client_id:
            client_req_ids.add(r.get("id"))
    req_id_set = client_req_ids

    # Count successful attempts today/month
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    succ_today = 0
    succ_month = 0
    for a in attempts:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "succeeded":
            continue
        # must belong to this client via request
        rid = a.get("request_id")
        if rid not in client_req_ids:
            continue
        d = _dt_parse(a.get("created_at"))
        if not d:
            continue
        if d >= day_start:
            succ_today += 1
        if d >= month_start:
            succ_month += 1

    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0 or not isinstance(monthly_limit, int) or monthly_limit < 0:
        _log("get_citeas_data", client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "Client quota configuration invalid")

    if succ_today + 1 > daily_limit or succ_month + 1 > monthly_limit:
        _log("get_citeas_data", client_id, "error", "quota_exceeded")
        return _err("QUOTA_EXCEEDED", "Citation retrieval quota exceeded")

    # ---- create provider_attempt (also transitions request queued->running only once)
    parent = existing_req
    if parent.get("status") not in ("queued", "running"):
        _log("get_citeas_data", client_id, "error", "invalid_transition")
        return _err("INVALID_TRANSITION", "Cannot start provider attempt for a terminal request")

    # attempt_no increment (<=10)
    req_id = parent.get("id")
    max_no = 0
    for a in attempts:
        if isinstance(a, dict) and a.get("request_id") == req_id:
            try:
                max_no = max(max_no, int(a.get("attempt_no") or 0))
            except Exception:
                pass
    if max_no >= 10:
        _log("get_citeas_data", client_id, "error", "quota_exceeded")
        return _err("QUOTA_EXCEEDED", "Maximum attempts reached for this request")

    # queued->running only once
    if parent.get("status") == "queued":
        parent["status"] = "running"
        parent["updated_at"] = now_iso

    attempt_id = _new_id("pa")
    attempt_no = max_no + 1
    attempt_row = {
        "id": attempt_id,
        "request_id": req_id,
        "attempt_no": attempt_no,
        "provider": "citeas",
        "status": "started",
        "http_status": 200,
        "latency_ms": None,
        "raw_response": None,
        "parse_status": "not_parsed",
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    attempts.append(attempt_row)

    # Persist running status + attempt started
    try:
        _save("citation_requests.json", reqs)
        _save("provider_attempts.json", attempts)
    except Exception:
        _log("get_citeas_data", client_id, "error", "storage_error")
        return _err("CONFLICT", "Failed to persist attempt creation")

    # ---- "upstream" retrieval simulation: deterministic success unless input looks invalid
    # If resource is extremely short, treat as invalid_input/not_found
    if len(resource_norm) < 3:
        attempt_row["status"] = "failed"
        attempt_row["parse_status"] = "not_parsed"
        attempt_row["error_code"] = "bad_response"
        attempt_row["error_message"] = "Resource identifier too short"
        attempt_row["updated_at"] = now_iso

        parent["status"] = "failed"
        parent["error_code"] = "invalid_input"
        parent["error_message"] = "Resource identifier too short"
        parent["updated_at"] = now_iso

        try:
            _save("provider_attempts.json", attempts)
            _save("citation_requests.json", reqs)
        except Exception:
            _log("get_citeas_data", client_id, "error", "storage_error")
            return _err("CONFLICT", "Failed to persist failure outcome")

        _log("get_citeas_data", client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "resource is invalid")

    # Create a deterministic BibTeX
    safe_key = re.sub(r"[^A-Za-z0-9]+", "", resource_norm.lower())[:24] or "cite"
    bibtex = (
        f"@misc{{{safe_key},\n"
        f"  title = {{{resource.strip()}}},\n"
        f"  howpublished = {{{resource_norm}}},\n"
        f"  note = {{Retrieved via CiteAs}},\n"
        f"  year = {{{now.year}}}\n"
        f"}}\n"
    )

    attempt_row["status"] = "succeeded"
    attempt_row["parse_status"] = "parsed"
    attempt_row["raw_response"] = bibtex
    attempt_row["latency_ms"] = int((time.time() - t0) * 1000)
    attempt_row["updated_at"] = now_iso

    # Publication handling (best-effort): if DOI normalized, upsert by DOI
    pub_id = None
    doi_val = None
    if resource_norm.startswith("doi:"):
        doi_val = resource_norm[4:].strip().lower()
        # find existing by doi
        for p in pubs:
            if isinstance(p, dict) and (p.get("doi") or "").lower() == doi_val and p.get("status") != "deleted":
                pub_id = p.get("id")
                break
        if pub_id is None:
            # create new publication with unique DOI
            pub_id = _new_id("pub")
            pubs.append({
                "id": pub_id,
                "canonical_title": resource.strip(),
                "doi": doi_val,
                "url": None,
                "year": now.year,
                "authors": None,
                "source_provider": "citeas",
                "status": "active",
                "merged_into_publication_id": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            })

    # Create citation result_rank=1, unique(request_id,result_rank)
    # If already exists (idempotency for retried tool call where request is running), update/return existing active.
    existing_cit = None
    for x in cits:
        if isinstance(x, dict) and x.get("request_id") == req_id and x.get("result_rank") == 1:
            existing_cit = x
            break

    if existing_cit is None:
        cit_id = _new_id("cit")
        cit_row = {
            "id": cit_id,
            "request_id": req_id,
            "attempt_id": attempt_id,
            "publication_id": pub_id,
            "provider": "citeas",
            "result_rank": 1,
            "bibtex": bibtex,
            "bibtex_key": _extract_bibtex_key(bibtex),
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cits.append(cit_row)
    else:
        # If it exists, ensure active and refresh fields
        existing_cit["attempt_id"] = existing_cit.get("attempt_id") or attempt_id
        existing_cit["publication_id"] = existing_cit.get("publication_id") or pub_id
        existing_cit["bibtex"] = bibtex
        existing_cit["bibtex_key"] = _extract_bibtex_key(bibtex)
        existing_cit["updated_at"] = now_iso
        if existing_cit.get("status") == "deleted":
            existing_cit["status"] = "active"

    # Mark request succeeded (terminal)
    parent["status"] = "succeeded"
    parent["error_code"] = None
    parent["error_message"] = None
    parent["cache_hit"] = False
    parent["updated_at"] = now_iso

    try:
        _save("provider_attempts.json", attempts)
        _save("publications.json", pubs)
        _save("citations.json", cits)
        _save("citation_requests.json", reqs)
    except Exception:
        _log("get_citeas_data", client_id, "error", "storage_error")
        return _err("CONFLICT", "Failed to persist success outcome")

    # Return exactly one citation
    out_cit = None
    for x in cits:
        if isinstance(x, dict) and x.get("request_id") == req_id and x.get("result_rank") == 1 and x.get("status") == "active":
            out_cit = x
            break
    if out_cit is None:
        _log("get_citeas_data", client_id, "error", "not_found")
        return _err("NOT_FOUND", "Citation could not be produced")

    _log("get_citeas_data", client_id, "ok", "fresh")
    return {
        "request": parent,
        "citations": [out_cit],
        "cached": False,
    }

def get_scholar_data(query, results=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now_iso + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _norm_query(x):
        x = x.strip()
        x = re.sub(r"\s+", " ", x)
        return x

    def _cache_key(provider, query_norm, results_requested):
        base = f"{provider}|{query_norm}|{int(results_requested)}"
        ck = hashlib.sha256(base.encode("utf-8")).hexdigest()
        return f"ck_{ck}"

    def _extract_bibtex_key(bibtex):
        m = re.search(r"@\w+\s*\{\s*([^,\s]+)\s*,", bibtex or "", flags=re.IGNORECASE)
        return m.group(1) if m else None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, client_id, status, detail=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rl"),
            "endpoint": endpoint,
            "client_id": client_id,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            return
        return

    # ---- validation
    if not isinstance(query, str) or not query.strip():
        _log("get_scholar_data", None, "error", "validation_error")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if results is None:
        results_requested = 2
    else:
        if not isinstance(results, int):
            _log("get_scholar_data", None, "error", "validation_error")
            return _err("VALIDATION_ERROR", "results must be an integer")
        results_requested = results
    if results_requested < 1 or results_requested > 50:
        _log("get_scholar_data", None, "error", "validation_error")
        return _err("VALIDATION_ERROR", "results must be between 1 and 50")

    # ---- ambient auth
    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        _log("get_scholar_data", None, "error", "unauthorized")
        return _err("UNAUTHORIZED", "No active API client is permitted to use the service")
    client = active_clients[0]
    client_id = client.get("id")

    # ---- cache key + reuse/create request
    query_norm = _norm_query(query)
    ck = _cache_key("scholar", query_norm, results_requested)
    if not (8 <= len(ck) <= 256):
        _log("get_scholar_data", client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "cache_key length invalid (internal)")

    reqs = _load("citation_requests.json")
    cits = _load("citations.json")
    attempts = _load("provider_attempts.json")
    pubs = _load("publications.json")

    existing_req = None
    for r in reqs:
        if isinstance(r, dict) and r.get("client_id") == client_id and r.get("cache_key") == ck:
            existing_req = r
            break

    if existing_req and existing_req.get("status") == "succeeded":
        req_id = existing_req.get("id")
        matched = [x for x in cits if isinstance(x, dict) and x.get("request_id") == req_id and x.get("status") == "active" and x.get("provider") == "scholar"]
        matched.sort(key=lambda x: x.get("result_rank") or 0)
        # must be contiguous from 1..n
        if matched and matched[0].get("result_rank") == 1:
            contiguous = True
            for i, m in enumerate(matched, start=1):
                if m.get("result_rank") != i:
                    contiguous = False
                    break
            if contiguous:
                existing_req["cache_hit"] = True
                existing_req["updated_at"] = now_iso
                try:
                    _save("citation_requests.json", reqs)
                except Exception:
                    _log("get_scholar_data", client_id, "error", "storage_error")
                    return _err("CONFLICT", "Failed to persist cache_hit update")
                _log("get_scholar_data", client_id, "ok", "cache_hit")
                return {"request": existing_req, "citations": matched[:results_requested], "cached": True}

    if existing_req and existing_req.get("status") in ("succeeded", "failed", "cancelled"):
        _log("get_scholar_data", client_id, "error", "not_found")
        return _err("NOT_FOUND", "No cached citations available for this query")

    if existing_req is None:
        req_id = _new_id("cr")
        new_req = {
            "id": req_id,
            "client_id": client_id,
            "provider": "scholar",
            "resource": None,
            "query": query,
            "results_requested": results_requested,
            "status": "queued",
            "cache_key": ck,
            "cache_hit": False,
            "error_code": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(new_req)
        existing_req = new_req
        try:
            _save("citation_requests.json", reqs)
        except Exception:
            _log("get_scholar_data", client_id, "error", "storage_error")
            return _err("CONFLICT", "Failed to persist citation request")

    # ---- quota enforcement (successful attempts only; cached don't count)
    client_req_ids = set()
    for r in reqs:
        if isinstance(r, dict) and r.get("client_id") == client_id:
            client_req_ids.add(r.get("id"))

    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    succ_today = 0
    succ_month = 0
    for a in attempts:
        if not isinstance(a, dict) or a.get("status") != "succeeded":
            continue
        rid = a.get("request_id")
        if rid not in client_req_ids:
            continue
        d = _dt_parse(a.get("created_at"))
        if not d:
            continue
        if d >= day_start:
            succ_today += 1
        if d >= month_start:
            succ_month += 1

    daily_limit = client.get("daily_request_limit")
    monthly_limit = client.get("monthly_request_limit")
    if not isinstance(daily_limit, int) or daily_limit < 0 or not isinstance(monthly_limit, int) or monthly_limit < 0:
        _log("get_scholar_data", client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "Client quota configuration invalid")

    if succ_today + 1 > daily_limit or succ_month + 1 > monthly_limit:
        _log("get_scholar_data", client_id, "error", "quota_exceeded")
        return _err("QUOTA_EXCEEDED", "Citation retrieval quota exceeded")

    # ---- create provider_attempt (and set request to running if queued)
    parent = existing_req
    if parent.get("status") not in ("queued", "running"):
        _log("get_scholar_data", client_id, "error", "invalid_transition")
        return _err("INVALID_TRANSITION", "Cannot start provider attempt for a terminal request")
    req_id = parent.get("id")

    max_no = 0
    for a in attempts:
        if isinstance(a, dict) and a.get("request_id") == req_id:
            try:
                max_no = max(max_no, int(a.get("attempt_no") or 0))
            except Exception:
                pass
    if max_no >= 10:
        _log("get_scholar_data", client_id, "error", "quota_exceeded")
        return _err("QUOTA_EXCEEDED", "Maximum attempts reached for this request")

    if parent.get("status") == "queued":
        parent["status"] = "running"
        parent["updated_at"] = now_iso

    attempt_id = _new_id("pa")
    attempt_row = {
        "id": attempt_id,
        "request_id": req_id,
        "attempt_no": max_no + 1,
        "provider": "scholar",
        "status": "started",
        "http_status": 200,
        "latency_ms": None,
        "raw_response": None,
        "parse_status": "not_parsed",
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    attempts.append(attempt_row)

    try:
        _save("citation_requests.json", reqs)
        _save("provider_attempts.json", attempts)
    except Exception:
        _log("get_scholar_data", client_id, "error", "storage_error")
        return _err("CONFLICT", "Failed to persist attempt creation")

    # ---- "upstream" deterministic results
    # If query is too short, fail
    if len(query_norm) < 3:
        attempt_row["status"] = "failed"
        attempt_row["parse_status"] = "not_parsed"
        attempt_row["error_code"] = "bad_response"
        attempt_row["error_message"] = "Query too short"
        attempt_row["updated_at"] = now_iso

        parent["status"] = "failed"
        parent["error_code"] = "invalid_input"
        parent["error_message"] = "Query too short"
        parent["updated_at"] = now_iso

        try:
            _save("provider_attempts.json", attempts)
            _save("citation_requests.json", reqs)
        except Exception:
            _log("get_scholar_data", client_id, "error", "storage_error")
            return _err("CONFLICT", "Failed to persist failure outcome")

        _log("get_scholar_data", client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "query is invalid")

    # Create between 1 and results_requested citations
    # Ensure no gaps, ranks start at 1
    produced_n = results_requested
    if " no results" in query_norm.lower() or query_norm.lower().startswith("zzzz"):
        produced_n = 1

    # supersede any existing active citations for this request with ranks that will be re-used (idempotent refresh)
    # (keep unique(request_id,result_rank))
    by_rank = {}
    for x in cits:
        if isinstance(x, dict) and x.get("request_id") == req_id and x.get("provider") == "scholar":
            by_rank[x.get("result_rank")] = x

    out_rows = []
    for rank in range(1, produced_n + 1):
        title = f"{query_norm} (Result {rank})"
        key = re.sub(r"[^A-Za-z0-9]+", "", (query_norm.lower() + str(rank)))[:20] or f"r{rank}"
        bibtex = (
            f"@article{{{key},\n"
            f"  title = {{{title}}},\n"
            f"  author = {{Unknown}},\n"
            f"  journal = {{Google Scholar}},\n"
            f"  year = {{{now.year}}}\n"
            f"}}\n"
        )

        # Create publication (no DOI)
        pub_id = _new_id("pub")
        pubs.append({
            "id": pub_id,
            "canonical_title": title,
            "doi": None,
            "url": None,
            "year": now.year,
            "authors": ["Unknown"],
            "source_provider": "scholar",
            "status": "active",
            "merged_into_publication_id": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        })

        existing = by_rank.get(rank)
        if existing is None:
            cit_row = {
                "id": _new_id("cit"),
                "request_id": req_id,
                "attempt_id": attempt_id,
                "publication_id": pub_id,
                "provider": "scholar",
                "result_rank": rank,
                "bibtex": bibtex,
                "bibtex_key": _extract_bibtex_key(bibtex),
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            cits.append(cit_row)
            out_rows.append(cit_row)
        else:
            # refresh existing
            if existing.get("status") == "deleted":
                existing["status"] = "active"
            existing["attempt_id"] = existing.get("attempt_id") or attempt_id
            existing["publication_id"] = existing.get("publication_id") or pub_id
            existing["bibtex"] = bibtex
            existing["bibtex_key"] = _extract_bibtex_key(bibtex)
            existing["updated_at"] = now_iso
            out_rows.append(existing)

    attempt_row["status"] = "succeeded"
    attempt_row["parse_status"] = "parsed"
    attempt_row["raw_response"] = f"{produced_n} citations"
    attempt_row["latency_ms"] = int((time.time() - t0) * 1000)
    attempt_row["updated_at"] = now_iso

    parent["status"] = "succeeded"
    parent["error_code"] = None
    parent["error_message"] = None
    parent["cache_hit"] = False
    parent["updated_at"] = now_iso

    try:
        _save("publications.json", pubs)
        _save("citations.json", cits)
        _save("provider_attempts.json", attempts)
        _save("citation_requests.json", reqs)
    except Exception:
        _log("get_scholar_data", client_id, "error", "storage_error")
        return _err("CONFLICT", "Failed to persist success outcome")

    # Reload citations for this request and return up to results_requested (should be produced_n)
    matched = [x for x in cits if isinstance(x, dict) and x.get("request_id") == req_id and x.get("status") == "active" and x.get("provider") == "scholar"]
    matched.sort(key=lambda x: x.get("result_rank") or 0)
    # enforce contiguous 1..n
    contiguous = []
    expected = 1
    for x in matched:
        if x.get("result_rank") == expected:
            contiguous.append(x)
            expected += 1
        else:
            break
    if not contiguous:
        _log("get_scholar_data", client_id, "error", "not_found")
        return _err("NOT_FOUND", "No citations produced")

    _log("get_scholar_data", client_id, "ok", "fresh")
    return {"request": parent, "citations": contiguous[:results_requested], "cached": False}

def list_citation_requests(provider=None, status=None, cache_key=None, client_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + '|' + now_iso + '|' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _dt_parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log(endpoint, resolved_client_id, status_s, detail=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        logs.append({
            "id": _new_id("rl"),
            "endpoint": endpoint,
            "client_id": resolved_client_id,
            "status": status_s,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        try:
            _save("request_logs.json", logs)
        except Exception:
            return

    # ambient auth
    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not active_clients:
        _log("list_citation_requests", None, "error", "unauthorized")
        return _err("UNAUTHORIZED", "No active API client is permitted to use the service")
    caller_client = active_clients[0]
    caller_client_id = caller_client.get("id")

    # validate filters
    if provider is not None:
        if provider not in ("citeas", "scholar"):
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "Invalid provider")
    if status is not None:
        if status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "Invalid status")
    if cache_key is not None and (not isinstance(cache_key, str) or not cache_key):
        _log("list_citation_requests", caller_client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "cache_key must be a non-empty string when provided")

    # Cross-client visibility is not modeled; only allow client_id filter if it matches caller
    if client_id is not None:
        if not isinstance(client_id, str) or not client_id:
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "client_id must be a non-empty string")
        if client_id != caller_client_id:
            _log("list_citation_requests", caller_client_id, "error", "unauthorized")
            return _err("UNAUTHORIZED", "Not permitted to list other clients' requests")
        effective_client_id = client_id
    else:
        effective_client_id = caller_client_id

    ca = _dt_parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        _log("list_citation_requests", caller_client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time")
    cb = _dt_parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        _log("list_citation_requests", caller_client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time")
    if ca and cb and ca > cb:
        _log("list_citation_requests", caller_client_id, "error", "validation_error")
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    if limit is None:
        lim = 50
    else:
        if not isinstance(limit, int):
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        lim = limit

    # cursor: opaque base64 of {"created_at": "...", "id": "..."}
    after_created = None
    after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
            after_created = _dt_parse_rfc3339(payload.get("created_at"))
            after_id = payload.get("id")
            if after_created is None or not isinstance(after_id, str) or not after_id:
                raise ValueError("bad cursor")
        except Exception:
            _log("list_citation_requests", caller_client_id, "error", "validation_error")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # load + filter
    reqs = _load("citation_requests.json")
    rows = []
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != effective_client_id:
            continue
        if provider is not None and r.get("provider") != provider:
            continue
        if status is not None and r.get("status") != status:
            continue
        if cache_key is not None and r.get("cache_key") != cache_key:
            continue
        d = _dt_parse_rfc3339(r.get("created_at"))
        if ca and d and d < ca:
            continue
        if cb and d and d >= cb:
            continue
        if ca and d is None:
            continue
        if cb and d is None:
            continue
        rows.append(r)

    # order created_at desc, then id desc for stability
    def _sort_key(r):
        d = _dt_parse_rfc3339(r.get("created_at"))
        if d is None:
            d = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (d, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)

    # apply cursor: return items strictly after cursor in this ordering (desc)
    if after_created is not None and after_id is not None:
        filtered = []
        for r in rows:
            d = _dt_parse_rfc3339(r.get("created_at"))
            if d is None:
                d = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            rid = r.get("id") or ""
            # In desc order, "after" means (d, id) < (after_created, after_id)
            if (d < after_created) or (d == after_created and rid < after_id):
                filtered.append(r)
        rows = filtered

    page = rows[:lim]
    has_more = len(rows) > lim
    next_cursor = None
    if page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        try:
            next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        except Exception:
            next_cursor = None

    _log("list_citation_requests", caller_client_id, "ok", None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
    }

def get_citation_request(id, include_citations=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_s, client_id=None, request_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "log_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": "get_citation_request",
            "client_id": client_id,
            "request_id": request_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(id, str) or not id.strip():
            _log("validation_error", detail="bad id")
            return _err("VALIDATION_ERROR", "id must be a non-empty string.")
        if include_citations is None:
            include_citations = False
        if not isinstance(include_citations, bool):
            _log("validation_error", request_id=id, detail="bad include_citations")
            return _err("VALIDATION_ERROR", "include_citations must be a boolean when provided.")

        reqs = _load("citation_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        req = next((r for r in reqs if isinstance(r, dict) and r.get("id") == id), None)
        if req is None:
            _log("not_found", request_id=id, detail="citation_request not found")
            return _err("NOT_FOUND", "Citation request not found.")

        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("id") == req.get("client_id")), None)

        # If the request references a missing/deleted client, treat as not visible (NOT_FOUND) rather than leaking existence.
        if client is None or client.get("status") == "deleted":
            _log("not_found", client_id=req.get("client_id"), request_id=id, detail="request not visible (client missing/deleted)")
            return _err("NOT_FOUND", "Citation request not found.")

        out_req = dict(req)

        out_cits = None
        if include_citations:
            cits = _load("citations.json")
            if not isinstance(cits, list):
                cits = []
            # Return citations sorted by result_rank (and stable by created_at/id)
            matched = [c for c in cits if isinstance(c, dict) and c.get("request_id") == id]
            def _rk(x):
                rr = x.get("result_rank")
                try:
                    rr = int(rr)
                except Exception:
                    rr = 10**9
                return (rr, x.get("created_at") or "", x.get("id") or "")
            matched.sort(key=_rk)
            out_cits = matched

        resp = {
            "citation_request": out_req,
            "include_citations": bool(include_citations),
        }
        if include_citations:
            resp["citations"] = out_cits

        _log("ok", client_id=client.get("id"), request_id=id)
        return resp
    except Exception as e:
        _log("error", request_id=id, detail=f"internal_error: {type(e).__name__}")
        return _err("UNKNOWN", "Internal error.")

def create_citation_request(provider, resource=None, query=None, results_requested=None, cache_key=None, **_extra):
    import json, os, datetime, re, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(client_id, endpoint, status, detail=None, request_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "log_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": endpoint,
            "client_id": client_id,
            "request_id": request_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            **({"detail": detail} if detail is not None else {}),
        })
        _save("request_logs.json", logs)

    def _pick_active_client():
        clients = _load("api_clients.json")
        if not isinstance(clients, list): return None
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active: return None
        # Prefer higher limits
        active.sort(key=lambda c: (int(c.get("daily_request_limit", 0) or 0), int(c.get("monthly_request_limit", 0) or 0)), reverse=True)
        return active[0]

    def _norm_ws(s):
        s = s.strip()
        s = re.sub(r"\s+", " ", s)
        return s

    def _compute_cache_key(p, r, q, rr):
        if p == "citeas":
            base = f"citeas:r:{_norm_ws(r or '')}"
        else:
            base = f"scholar:q:{_norm_ws(q or '')}|n:{int(rr)}"
        if len(base) < 8:
            base = (base + "________")[:8]
        if len(base) > 256:
            base = base[:256]
        return base

    def _new_id(prefix):
        # stable-ish unique id with time+random
        h = hashlib.sha256((prefix + "|" + now + "|" + uuid.uuid4().hex).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{h}"

    # Validate provider
    if not isinstance(provider, str) or provider not in ("citeas", "scholar"):
        _log(None, "create_citation_request", "validation_error", detail="bad provider")
        return _err("VALIDATION_ERROR", "provider must be one of: 'citeas', 'scholar'.")

    # Validate & normalize provider-specific fields.
    # IMPORTANT: be permissive with extra fields (do not reject if query/resource provided but irrelevant);
    # enforce only what schema/business rules require for stored request.
    norm_resource = resource if isinstance(resource, str) else None
    norm_query = query if isinstance(query, str) else None

    if provider == "citeas":
        if norm_resource is None or not norm_resource.strip():
            _log(None, "create_citation_request", "validation_error", detail="missing resource for citeas")
            return _err("VALIDATION_ERROR", "resource is required when provider='citeas'.")
        norm_resource = norm_resource.strip()
        # Stored fields must satisfy constraint: query/results_requested null
        stored_query = None
        stored_results = None
    else:
        if norm_query is None or not norm_query.strip():
            _log(None, "create_citation_request", "validation_error", detail="missing query for scholar")
            return _err("VALIDATION_ERROR", "query is required when provider='scholar'.")
        stored_query = _norm_ws(norm_query)
        if results_requested is None:
            stored_results = 2
        else:
            if not isinstance(results_requested, int):
                _log(None, "create_citation_request", "validation_error", detail="results_requested not int")
                return _err("VALIDATION_ERROR", "results_requested must be an integer when provided.")
            if results_requested < 1 or results_requested > 50:
                _log(None, "create_citation_request", "validation_error", detail="results_requested out of range")
                return _err("VALIDATION_ERROR", "results_requested must be between 1 and 50.")
            stored_results = results_requested
        stored_resource = None

    # cache_key
    if cache_key is not None and not isinstance(cache_key, str):
        _log(None, "create_citation_request", "validation_error", detail="cache_key not string")
        return _err("VALIDATION_ERROR", "cache_key must be a string when provided.")

    if provider == "citeas":
        computed = _compute_cache_key(provider, norm_resource, None, None)
    else:
        computed = _compute_cache_key(provider, None, stored_query, stored_results)

    final_cache_key = (cache_key.strip() if isinstance(cache_key, str) else computed)
    if not (8 <= len(final_cache_key) <= 256):
        _log(None, "create_citation_request", "validation_error", detail="cache_key length")
        return _err("VALIDATION_ERROR", "cache_key length must be between 8 and 256 characters.")

    # Ambient auth: must have an active client
    client = _pick_active_client()
    if client is None:
        _log(None, "create_citation_request", "unauthorized", detail="no active client")
        return _err("UNAUTHORIZED", "No active API client available for this call.")

    # Reuse existing (client_id, cache_key) if exists; idempotent behavior
    reqs = _load("citation_requests.json")
    if not isinstance(reqs, list): reqs = []
    existing = None
    for r in reqs:
        if isinstance(r, dict) and r.get("client_id") == client.get("id") and r.get("cache_key") == final_cache_key:
            existing = r
            break

    if existing is not None:
        # Do not change terminal states; only touch updated_at (allowed).
        existing["updated_at"] = now
        _save("citation_requests.json", reqs)
        _log(client.get("id"), "create_citation_request", "ok", detail="reused", request_id=existing.get("id"))
        return {"citation_request": dict(existing), "reused": True}

    # Create new request row; initial state queued
    req_id = _new_id("citeas_req")
    new_row = {
        "id": req_id,
        "client_id": client.get("id"),
        "provider": provider,
        "resource": (norm_resource.strip() if provider == "citeas" else None),
        "query": (stored_query if provider == "scholar" else None),
        "results_requested": (stored_results if provider == "scholar" else None),
        "status": "queued",
        "cache_key": final_cache_key,
        "cache_hit": False,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    reqs.append(new_row)
    _save("citation_requests.json", reqs)
    _log(client.get("id"), "create_citation_request", "ok", request_id=req_id)
    return {"citation_request": dict(new_row), "reused": False}

def cancel_citation_request(id, reason=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_s, client_id=None, request_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "log_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": "cancel_citation_request",
            "client_id": client_id,
            "request_id": request_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(id, str) or not id.strip():
            _log("validation_error", detail="bad id")
            return _err("VALIDATION_ERROR", "id must be a non-empty string.")
        if reason is not None and not isinstance(reason, str):
            _log("validation_error", request_id=id, detail="bad reason")
            return _err("VALIDATION_ERROR", "reason must be a string when provided.")

        reqs = _load("citation_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        idx = next((i for i, r in enumerate(reqs) if isinstance(r, dict) and r.get("id") == id), None)
        if idx is None:
            _log("not_found", request_id=id, detail="citation_request not found")
            return _err("NOT_FOUND", "Citation request not found.")

        req = reqs[idx]

        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("id") == req.get("client_id")), None)

        # Not visible -> NOT_FOUND (avoid leaking)
        if client is None or client.get("status") == "deleted":
            _log("not_found", client_id=req.get("client_id"), request_id=id, detail="request not visible (client missing/deleted)")
            return _err("NOT_FOUND", "Citation request not found.")

        st = req.get("status")
        if st in ("succeeded", "failed", "cancelled"):
            _log("conflict", client_id=client.get("id"), request_id=id, detail=f"already terminal status={st}")
            return _err("CONFLICT", "Citation request is already terminal and cannot be cancelled.", status=st)

        if st not in ("queued", "running"):
            _log("validation_error", client_id=client.get("id"), request_id=id, detail=f"invalid status value={st}")
            return _err("VALIDATION_ERROR", "Citation request has an invalid status value.", status=st)

        # Valid transition: queued/running -> cancelled
        req["status"] = "cancelled"
        req["updated_at"] = now
        if reason is not None and reason.strip():
            # Store in error_message for a human-readable cancellation reason (no dedicated field in schema)
            req["error_message"] = reason.strip()
            # Keep error_code unset for cancellations to avoid violating enum (error_code is for failed).
            if "error_code" in req and req.get("error_code") is not None:
                req["error_code"] = None

        reqs[idx] = req
        _save("citation_requests.json", reqs)

        _log("ok", client_id=client.get("id"), request_id=id)
        return {"citation_request": dict(req)}
    except Exception as e:
        _log("error", request_id=id, detail=f"internal_error: {type(e).__name__}")
        return _err("UNKNOWN", "Internal error.")

def create_provider_attempt(request_id, status, http_status=None, latency_ms=None, raw_response=None, parse_status=None, error_code=None, error_message=None, citations=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0518000" if __import__("os").path.isdir("./environment_mix/0518000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    today = now_dt.date()
    month_key = (now_dt.year, now_dt.month)

    def _log(status_s, client_id=None, req_id=None, attempt_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "log_" + uuid.uuid4().hex,
            "ts": now,
            "endpoint": "create_provider_attempt",
            "client_id": client_id,
            "request_id": req_id,
            "attempt_id": attempt_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _norm_doi(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        x = s.strip()
        x = re.sub(r"^doi:\s*", "", x, flags=re.I)
        x = re.sub(r"^https?://(dx\.)?doi\.org/", "", x, flags=re.I)
        x = x.strip().lower()
        return x or None

    def _extract_bibtex_key(bibtex):
        if not isinstance(bibtex, str):
            return None
        m = re.search(r"@\w+\s*\{\s*([^,\s]+)\s*,", bibtex)
        return m.group(1) if m else None

    try:
        # Validate required
        if not isinstance(request_id, str) or not request_id.strip():
            _log("validation_error", detail="bad request_id")
            return _err("VALIDATION_ERROR", "request_id must be a non-empty string.")
        if status not in ("started", "succeeded", "failed"):
            _log("validation_error", req_id=request_id, detail="bad status")
            return _err("VALIDATION_ERROR", "status must be one of: started, succeeded, failed.")

        # Validate optionals
        if http_status is not None:
            if not isinstance(http_status, int) or http_status < 100 or http_status > 599:
                _log("validation_error", req_id=request_id, detail="bad http_status")
                return _err("VALIDATION_ERROR", "http_status must be an integer between 100 and 599 when provided.")
        if latency_ms is not None:
            if not isinstance(latency_ms, int) or latency_ms < 0:
                _log("validation_error", req_id=request_id, detail="bad latency_ms")
                return _err("VALIDATION_ERROR", "latency_ms must be a non-negative integer when provided.")
        if raw_response is not None and not isinstance(raw_response, str):
            _log("validation_error", req_id=request_id, detail="bad raw_response")
            return _err("VALIDATION_ERROR", "raw_response must be a string when provided.")
        if parse_status is None:
            parse_status = "not_parsed"
        if parse_status not in ("not_parsed", "parsed", "parse_failed"):
            _log("validation_error", req_id=request_id, detail="bad parse_status")
            return _err("VALIDATION_ERROR", "parse_status must be one of: not_parsed, parsed, parse_failed.")
        if error_code is not None and not isinstance(error_code, str):
            _log("validation_error", req_id=request_id, detail="bad error_code type")
            return _err("VALIDATION_ERROR", "error_code must be a string when provided.")
        if error_message is not None and not isinstance(error_message, str):
            _log("validation_error", req_id=request_id, detail="bad error_message type")
            return _err("VALIDATION_ERROR", "error_message must be a string when provided.")
        if citations is not None and not isinstance(citations, list):
            _log("validation_error", req_id=request_id, detail="bad citations type")
            return _err("VALIDATION_ERROR", "citations must be an array when provided.")

        # Load parent request
        reqs = _load("citation_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        req_idx = next((i for i, r in enumerate(reqs) if isinstance(r, dict) and r.get("id") == request_id), None)
        if req_idx is None:
            _log("not_found", req_id=request_id, detail="parent request not found")
            return _err("NOT_FOUND", "Citation request not found.")
        req = reqs[req_idx]

        provider = req.get("provider")
        if provider not in ("citeas", "scholar"):
            _log("validation_error", req_id=request_id, detail=f"invalid request provider={provider}")
            return _err("VALIDATION_ERROR", "Parent request has an invalid provider.", provider=provider)

        # Visibility/auth via owning client existence
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("id") == req.get("client_id")), None)
        if client is None or client.get("status") == "deleted":
            _log("not_found", client_id=req.get("client_id"), req_id=request_id, detail="request not visible (client missing/deleted)")
            return _err("NOT_FOUND", "Citation request not found.")
        if client.get("status") != "active":
            _log("unauthorized", client_id=client.get("id"), req_id=request_id, detail=f"client status={client.get('status')}")
            return _err("UNAUTHORIZED", "Caller is not permitted to create provider attempts for this client.")

        # Parent request must be queued or running
        req_status = req.get("status")
        if req_status in ("succeeded", "failed", "cancelled"):
            _log("conflict", client_id=client.get("id"), req_id=request_id, detail=f"request terminal status={req_status}")
            return _err("CONFLICT", "Cannot create provider attempts for a terminal citation request.", status=req_status)
        if req_status not in ("queued", "running"):
            _log("validation_error", client_id=client.get("id"), req_id=request_id, detail=f"invalid request status={req_status}")
            return _err("VALIDATION_ERROR", "Parent request has an invalid status value.", status=req_status)

        # Determine next attempt_no (unique per request, max 10)
        attempts = _load("provider_attempts.json")
        if not isinstance(attempts, list):
            attempts = []
        req_attempts = [a for a in attempts if isinstance(a, dict) and a.get("request_id") == request_id]
        max_no = 0
        for a in req_attempts:
            try:
                n = int(a.get("attempt_no") or 0)
            except Exception:
                n = 0
            if n > max_no:
                max_no = n
        next_no = max_no + 1
        if next_no > 10:
            _log("conflict", client_id=client.get("id"), req_id=request_id, detail="attempt_no exceeded 10")
            return _err("CONFLICT", "Maximum attempt count exceeded for this request (max 10).", attempt_no=next_no)

        # Quota enforcement: counts only successful attempts (provider_attempts.status == 'succeeded')
        # and only when starting a NEW attempt. (cached responses do not come here.)
        daily_limit = client.get("daily_request_limit")
        monthly_limit = client.get("monthly_request_limit")
        if not isinstance(daily_limit, int) or daily_limit < 0:
            daily_limit = 0
        if not isinstance(monthly_limit, int) or monthly_limit < 0:
            monthly_limit = 0

        # Count successful attempts for this client by joining request_id -> client_id
        req_by_id = {r.get("id"): r for r in reqs if isinstance(r, dict) and isinstance(r.get("id"), str)}
        succ_today = 0
        succ_month = 0
        for a in attempts:
            if not isinstance(a, dict) or a.get("status") != "succeeded":
                continue
            pr = req_by_id.get(a.get("request_id"))
            if not isinstance(pr, dict) or pr.get("client_id") != client.get("id"):
                continue
            ts = _parse_ts(a.get("created_at"))
            if ts is None:
                continue
            if ts.date() == today:
                succ_today += 1
            if (ts.year, ts.month) == month_key:
                succ_month += 1

        # Starting a new attempt would add at most 1 successful attempt later, but rule says:
        # "reject starting ... if the client's successful attempts today would exceed limit"
        # Interpret as: if already at limit, do not allow creating new attempts.
        if daily_limit == 0 or monthly_limit == 0:
            # zero means no successful upstream attempts allowed
            _log("quota_exceeded", client_id=client.get("id"), req_id=request_id, detail="quota limit is 0")
            return _err("QUOTA_EXCEEDED", "Client quota exceeded.", daily_limit=daily_limit, monthly_limit=monthly_limit)
        if succ_today >= daily_limit:
            _log("quota_exceeded", client_id=client.get("id"), req_id=request_id, detail=f"daily quota exceeded {succ_today}/{daily_limit}")
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_limit=daily_limit, used_today=succ_today)
        if succ_month >= monthly_limit:
            _log("quota_exceeded", client_id=client.get("id"), req_id=request_id, detail=f"monthly quota exceeded {succ_month}/{monthly_limit}")
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", monthly_limit=monthly_limit, used_month=succ_month)

        # Validate citations payload based on provider + attempt status.
        # Accept valid calls even if citations omitted for started/failed.
        if status == "succeeded":
            if citations is None:
                _log("validation_error", client_id=client.get("id"), req_id=request_id, detail="succeeded attempt missing citations")
                return _err("VALIDATION_ERROR", "citations is required when status='succeeded'.")
            if len(citations) < 1:
                _log("validation_error", client_id=client.get("id"), req_id=request_id, detail="empty citations for succeeded")
                return _err("VALIDATION_ERROR", "citations must contain at least 1 item when status='succeeded'.")

        if citations is not None:
            # Basic item validation and provider match
            for i, c in enumerate(citations):
                if not isinstance(c, dict):
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail=f"citation[{i}] not object")
                    return _err("VALIDATION_ERROR", "Each citations item must be an object.", index=i)
                rr = c.get("result_rank")
                if not isinstance(rr, int) or rr < 1 or rr > 50:
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail=f"citation[{i}] bad result_rank")
                    return _err("VALIDATION_ERROR", "citations.result_rank must be an integer between 1 and 50.", index=i)
                cp = c.get("provider")
                if cp not in ("citeas", "scholar"):
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail=f"citation[{i}] bad provider")
                    return _err("VALIDATION_ERROR", "citations.provider must be 'citeas' or 'scholar'.", index=i)
                if cp != provider:
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail=f"citation[{i}] provider mismatch")
                    return _err("VALIDATION_ERROR", "citations.provider must match the parent request provider.", index=i)
                bib = c.get("bibtex")
                if not isinstance(bib, str) or len(bib.strip()) < 10:
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail=f"citation[{i}] bad bibtex")
                    return _err("VALIDATION_ERROR", "citations.bibtex must be a string of length >= 10.", index=i)

            # Provider-specific ranks
            ranks = sorted({c["result_rank"] for c in citations if isinstance(c, dict) and isinstance(c.get("result_rank"), int)})
            if provider == "citeas":
                if ranks != [1] or len(citations) != 1:
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail="citeas must have exactly one citation rank=1")
                    return _err("VALIDATION_ERROR", "For provider='citeas', citations must contain exactly one item with result_rank=1.")
            else:
                # scholar: contiguous starting at 1 up to results_requested
                results_requested = req.get("results_requested")
                if results_requested is None:
                    results_requested = 2
                try:
                    results_requested = int(results_requested)
                except Exception:
                    results_requested = 2
                if results_requested < 1 or results_requested > 50:
                    results_requested = 2
                expected = list(range(1, min(results_requested, len(ranks)) + 1))
                # Must be contiguous from 1 to max rank; and max rank <= results_requested
                if not ranks or ranks[0] != 1 or ranks != list(range(1, ranks[-1] + 1)) or ranks[-1] > results_requested:
                    _log("validation_error", client_id=client.get("id"), req_id=request_id, detail="scholar ranks not contiguous/within results_requested")
                    return _err("VALIDATION_ERROR", "For provider='scholar', citations must have contiguous result_rank starting at 1 and not exceed results_requested.", results_requested=results_requested)

        # If parent request is queued, transition to running (queued->running only once)
        if req_status == "queued":
            req["status"] = "running"
            req["updated_at"] = now
            reqs[req_idx] = req

        # Create attempt row
        attempt_id = _new_id("citeas_att")
        attempt = {
            "id": attempt_id,
            "request_id": request_id,
            "attempt_no": next_no,
            "provider": provider,
            "status": status,
            "http_status": http_status,
            "latency_ms": latency_ms,
            "raw_response": raw_response,
            "parse_status": parse_status,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }

        # Enforce attempt lifecycle enum and error fields lightly (schema has enum for provider_attempts.error_code)
        allowed_attempt_error_codes = {"timeout", "blocked", "rate_limited", "bad_response", "parse_error", "unknown"}
        if attempt["error_code"] is not None:
            if not isinstance(attempt["error_code"], str) or attempt["error_code"] not in allowed_attempt_error_codes:
                _log("validation_error", client_id=client.get("id"), req_id=request_id, detail="invalid attempt error_code enum")
                return _err("VALIDATION_ERROR", f"error_code must be one of {sorted(allowed_attempt_error_codes)} when provided.")

        # Mutations: insert attempt, and on success create/link publications and citations, and finalize request status.
        pubs = _load("publications.json")
        if not isinstance(pubs, list):
            pubs = []
        cits_store = _load("citations.json")
        if not isinstance(cits_store, list):
            cits_store = []

        created_pub_ids = set()
        created_citation_ids = []

        if status == "succeeded":
            # Create/replace citations for this request based on ranks (unique request_id,result_rank)
            existing_by_rank = {c.get("result_rank"): c for c in cits_store if isinstance(c, dict) and c.get("request_id") == request_id}

            for c in citations:
                rr = c["result_rank"]
                bib = c["bibtex"].strip()
                bibkey = c.get("bibtex_key")
                if bibkey is None:
                    bibkey = _extract_bibtex_key(bib)

                # Publication handling (optional)
                pub_id = None
                pub_obj = c.get("publication")
                if isinstance(pub_obj, dict) and pub_obj:
                    canonical_title = pub_obj.get("canonical_title")
                    doi_norm = _norm_doi(pub_obj.get("doi"))
                    url = pub_obj.get("url")
                    year = pub_obj.get("year")
                    authors = pub_obj.get("authors")
                    srcp = pub_obj.get("source_provider") or provider

                    if year is not None:
                        if not isinstance(year, int) or year < 1400 or year > 2200:
                            _log("validation_error", client_id=client.get("id"), req_id=request_id, attempt_id=attempt_id, detail="invalid publication year")
                            return _err("VALIDATION_ERROR", "publication.year must be between 1400 and 2200 when provided.")
                    if authors is not None:
                        if not isinstance(authors, list) or any(not isinstance(a, str) for a in authors):
                            _log("validation_error", client_id=client.get("id"), req_id=request_id, attempt_id=attempt_id, detail="invalid publication authors")
                            return _err("VALIDATION_ERROR", "publication.authors must be an array of strings when provided.")
                    if srcp not in ("citeas", "scholar"):
                        _log("validation_error", client_id=client.get("id"), req_id=request_id, attempt_id=attempt_id, detail="invalid publication source_provider")
                        return _err("VALIDATION_ERROR", "publication.source_provider must be 'citeas' or 'scholar' when provided.")

                    # Enforce DOI uniqueness: if DOI matches existing, link; else insert if canonical_title provided
                    existing_pub = None
                    if doi_norm:
                        existing_pub = next((p for p in pubs if isinstance(p, dict) and p.get("doi") == doi_norm), None)
                    if existing_pub is not None:
                        pub_id = existing_pub.get("id")
                    else:
                        if not isinstance(canonical_title, str) or not canonical_title.strip():
                            # Cannot insert without canonical_title per schema; but can still proceed with no publication link.
                            pub_id = None
                        else:
                            pub_id = _new_id("citeas_pub")
                            pub_row = {
                                "id": pub_id,
                                "canonical_title": canonical_title.strip(),
                                "doi": doi_norm,
                                "url": url if isinstance(url, str) and url.strip() else None,
                                "year": year if isinstance(year, int) else None,
                                "authors": authors if isinstance(authors, list) else None,
                                "source_provider": srcp,
                                "status": "active",
                                "merged_into_publication_id": None,
                                "created_at": now,
                                "updated_at": now,
                            }
                            pubs.append(pub_row)
                            created_pub_ids.add(pub_id)

                # Upsert citation row for (request_id, result_rank)
                prev = existing_by_rank.get(rr)
                if prev is not None:
                    # Make old one superseded and insert a new active row (keeps audit trail)
                    if prev.get("status") == "active":
                        prev["status"] = "superseded"
                        prev["updated_at"] = now
                    # Insert new
                cit_id = _new_id("citeas_cit")
                cit_row = {
                    "id": cit_id,
                    "request_id": request_id,
                    "attempt_id": attempt_id,
                    "publication_id": pub_id,
                    "provider": provider,
                    "result_rank": rr,
                    "bibtex": bib,
                    "bibtex_key": bibkey if isinstance(bibkey, str) and bibkey.strip() else None,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now,
                }
                cits_store.append(cit_row)
                created_citation_ids.append(cit_id)

            # Request succeeded (running->succeeded) allowed
            # If request is still queued (shouldn't be, but safe), set to running first then succeeded
            if req.get("status") == "queued":
                req["status"] = "running"
            if req.get("status") == "running":
                req["status"] = "succeeded"
            req["cache_hit"] = False
            req["error_code"] = None
            req["error_message"] = None
            req["updated_at"] = now
            reqs[req_idx] = req

        elif status == "failed":
            # Request running/queued -> failed allowed
            if req.get("status") == "queued":
                req["status"] = "running"
            if req.get("status") == "running":
                req["status"] = "failed"
            # Map attempt error_code to request error_code enum where possible
            allowed_req_error = {"upstream_timeout", "upstream_blocked", "not_found", "invalid_input", "rate_limited", "parse_error", "unknown"}
            mapped = None
            if isinstance(error_code, str):
                m = error_code.strip().lower()
                if m == "timeout":
                    mapped = "upstream_timeout"
                elif m == "blocked":
                    mapped = "upstream_blocked"
                elif m == "rate_limited":
                    mapped = "rate_limited"
                elif m == "parse_error":
                    mapped = "parse_error"
                elif m == "bad_response":
                    mapped = "unknown"
                elif m in allowed_req_error:
                    mapped = m
            req["cache_hit"] = False
            req["error_code"] = mapped or "unknown"
            req["error_message"] = error_message if isinstance(error_message, str) else req.get("error_message")
            req["updated_at"] = now
            reqs[req_idx] = req

        # Persist all changes
        attempts.append(attempt)
        _save("provider_attempts.json", attempts)
        _save("publications.json", pubs)
        _save("citations.json", cits_store)
        _save("citation_requests.json", reqs)

        _log("ok", client_id=client.get("id"), req_id=request_id, attempt_id=attempt_id)
        resp = {
            "provider_attempt": attempt,
            "citation_request": dict(reqs[req_idx]) if isinstance(reqs[req_idx], dict) else dict(req),
        }
        if created_citation_ids:
            resp["created_citation_ids"] = created_citation_ids
        if created_pub_ids:
            resp["created_publication_ids"] = sorted(created_pub_ids)
        return resp
    except Exception as e:
        _log("error", req_id=request_id, detail=f"internal_error: {type(e).__name__}")
        return _err("UNKNOWN", "Internal error.")
